/* Fiches des UE ajoutées en septembre 2026 : Physiologie, Médicament, Histologie / Embryologie.
   Même format que fiches.js (HTML Tailwind), concaténées dans FICHES_DATA. */

const H3 = (t) => `<h3 class="text-xl font-bold text-gray-900 mb-4">${t}</h3>`;
const H4 = (t) => `<h4 class="text-lg font-semibold text-gray-800 mb-2">${t}</h4>`;
const UL = (items) => `<ul class="list-disc pl-5 space-y-1 mb-4 text-gray-700">${items.map((i) => `<li>${i}</li>`).join('')}</ul>`;
const P = (t) => `<p class="mb-3">${t}</p>`;
const KEY = (color, t) => `<div class="bg-${color}-50 border border-${color}-200 rounded-xl p-4 mt-4"><p class="text-sm font-semibold text-${color}-800">Point clé concours : ${t}</p></div>`;

export const FICHES_EXTRA = [
  // ===== PHYSIOLOGIE =====
  { id: 'physiologie-homeostasie', subject: 'physiologie', title: 'Homéostasie et compartiments liquidiens', summary: 'Milieu intérieur, boucles de régulation et répartition de l’eau dans l’organisme.',
    content: H3('Homéostasie et compartiments') + H4('Le milieu intérieur') + UL(['<strong>Homéostasie</strong> (Claude Bernard, Cannon) : maintien des constantes du milieu intérieur (pH 7,40, glycémie ~1 g/L, température 37 °C, osmolarité ~290 mOsm/L) malgré les variations externes.', 'Boucle de <strong>rétrocontrôle négatif</strong> : capteur → centre intégrateur → effecteur, la réponse s’oppose à l’écart (thermorégulation, glycémie, pression artérielle).', '<strong>Rétrocontrôle positif</strong> : amplifie le signal jusqu’à un événement terminal (pic de LH, contractions utérines par l’ocytocine, coagulation).']) + H4('Compartiments liquidiens') + UL(['Eau totale ≈ <strong>60 %</strong> du poids chez l’homme adulte (50 % chez la femme, 75 % chez le nourrisson).', '<strong>Intracellulaire</strong> : 2/3 de l’eau totale (≈ 40 % du poids), riche en K+, Mg2+, phosphates, protéines.', '<strong>Extracellulaire</strong> : 1/3 (≈ 20 %), dont interstitiel 15 % et plasma 5 %. Riche en Na+, Cl-, HCO3-.', 'L’eau se déplace librement selon l’<strong>osmolarité</strong> ; le Na+ est le principal déterminant de l’osmolarité extracellulaire (osmolarité ≈ 2 × [Na+] + glycémie + urée, en mmol/L).', 'Le plasma diffère du liquide interstitiel par ses <strong>protéines</strong> (albumine) : pression oncotique qui retient l’eau dans les vaisseaux (équilibre de Starling).']) + KEY('sky', 'Une perte d’eau pure (déshydratation) concentre le Na+ : hypernatrémie et soif. Une hyponatrémie traduit un excès d’eau relatif, pas forcément un manque de sel. Retiens 60 / 40 / 20 / 15 / 5.') },
  { id: 'physiologie-potentiels', subject: 'physiologie', title: 'Potentiel de repos et potentiel d’action', summary: 'Gradients ioniques, équation de Nernst, canaux voltage-dépendants et conduction.',
    content: H3('Potentiels de membrane') + H4('Potentiel de repos') + UL(['Valeur ≈ <strong>−70 mV</strong> (neurone), −90 mV (muscle). Intérieur négatif.', 'Origine : perméabilité au <strong>K+</strong> dominante au repos (canaux de fuite) et pompe <strong>Na+/K+ ATPase</strong> (3 Na+ sortis pour 2 K+ entrés, électrogénique).', '<strong>Équation de Nernst</strong> : potentiel d’équilibre d’un ion E = (RT/zF) ln([ion]ext/[ion]int) ≈ 61 log([ext]/[int]) mV à 37 °C. E(K+) ≈ −90 mV, E(Na+) ≈ +60 mV.', 'Équation de Goldman : pondère chaque ion par sa perméabilité ; le potentiel de repos est proche de E(K+).']) + H4('Potentiel d’action') + UL(['Loi du <strong>tout ou rien</strong> : déclenché si le seuil (≈ −55 mV) est atteint ; amplitude constante, l’information est codée en fréquence.', '<strong>Dépolarisation</strong> : ouverture des canaux Na+ voltage-dépendants, entrée de Na+, pic vers +30 mV.', '<strong>Repolarisation</strong> : inactivation des canaux Na+, ouverture retardée des canaux K+, sortie de K+.', '<strong>Hyperpolarisation</strong> transitoire puis retour au repos ; la pompe Na+/K+ restaure les gradients à long terme.', '<strong>Périodes réfractaires</strong> : absolue (canaux Na+ inactivés, aucun PA possible) puis relative (PA possible avec stimulus plus fort). Elle impose le sens de propagation.']) + H4('Conduction') + UL(['Fibres <strong>myélinisées</strong> : conduction saltatoire de nœud de Ranvier en nœud de Ranvier, jusqu’à 120 m/s.', 'Vitesse ↑ avec le diamètre et la myélinisation (fibres Aα motrices rapides, fibres C amyéliniques lentes de la douleur).']) + KEY('sky', 'Les anesthésiques locaux bloquent les canaux Na+ voltage-dépendants : plus de dépolarisation, plus de PA. La tétrodotoxine fait de même. Une hyperkaliémie rapproche le potentiel de repos du seuil puis inactive les canaux Na+ : troubles du rythme.') },
  { id: 'physiologie-synapse', subject: 'physiologie', title: 'Transmission synaptique et jonction neuromusculaire', summary: 'Libération calcium-dépendante, récepteurs ionotropes et métabotropes, plaque motrice.',
    content: H3('La synapse chimique') + H4('Étapes de la transmission') + UL(['Arrivée du PA au bouton présynaptique → ouverture des <strong>canaux Ca2+ voltage-dépendants</strong> → entrée de Ca2+.', 'Fusion des vésicules (protéines SNARE) → <strong>exocytose</strong> du neurotransmetteur dans la fente (20-40 nm).', 'Fixation sur les récepteurs post-synaptiques → PPSE (dépolarisant, Na+) ou PPSI (hyperpolarisant, Cl- ou K+).', '<strong>Sommation</strong> spatiale et temporelle des potentiels post-synaptiques au cône d’émergence : le neurone décide de tirer ou non.', 'Fin du signal : recapture (sérotonine, noradrénaline, dopamine), dégradation enzymatique (acétylcholinestérase), diffusion.']) + H4('Récepteurs') + UL(['<strong>Ionotropes</strong> : canal ionique ligand-dépendant, réponse en millisecondes (nicotinique, GABA-A, AMPA/NMDA).', '<strong>Métabotropes</strong> : couplés aux protéines G, seconds messagers (AMPc, IP3), réponse lente et modulatrice (muscarinique, adrénergique, GABA-B, dopaminergique).', 'Principaux neurotransmetteurs : glutamate (excitateur majeur du SNC), GABA (inhibiteur majeur), acétylcholine, monoamines, peptides.']) + H4('Jonction neuromusculaire') + UL(['Motoneurone α → <strong>acétylcholine</strong> → récepteur nicotinique de la plaque motrice → potentiel de plaque, toujours supraliminaire chez le sujet sain.', 'Le PA musculaire se propage dans les tubules T, libère le Ca2+ du réticulum sarcoplasmique (récepteur à la ryanodine) : <strong>couplage excitation-contraction</strong>.', 'Acétylcholinestérase dans la fente : hydrolyse rapide de l’ACh.']) + KEY('sky', 'Myasthénie : auto-anticorps anti-récepteurs nicotiniques, fatigabilité musculaire ; les anticholinestérasiques l’améliorent. Curares : antagonistes nicotiniques. Toxine botulique : bloque l’exocytose (SNARE).') },
  { id: 'physiologie-sna', subject: 'physiologie', title: 'Système nerveux autonome', summary: 'Sympathique et parasympathique : anatomie fonctionnelle, neurotransmetteurs, récepteurs et effets.',
    content: H3('Le système nerveux autonome') + H4('Organisation') + UL(['Deux neurones en série : <strong>préganglionnaire</strong> (myélinisé, cholinergique, récepteur nicotinique ganglionnaire) et <strong>postganglionnaire</strong>.', '<strong>Sympathique</strong> : origine thoraco-lombaire (T1-L2), ganglions paravertébraux proches de la moelle, fibres postganglionnaires longues, noradrénergiques (sauf glandes sudoripares : ACh).', '<strong>Parasympathique</strong> : origine cranio-sacrée (nerfs III, VII, IX, X et S2-S4), ganglions près des organes, fibres postganglionnaires courtes, cholinergiques (récepteurs muscariniques).', 'Le nerf <strong>vague (X)</strong> assure 75 % de l’innervation parasympathique (cœur, poumons, tube digestif jusqu’au côlon transverse).', 'La <strong>médullosurrénale</strong> = ganglion sympathique modifié : sécrète adrénaline (80 %) et noradrénaline dans le sang.']) + H4('Récepteurs et effets') + UL(['<strong>α1</strong> : vasoconstriction, mydriase. <strong>α2</strong> : présynaptique, freine la libération de NA.', '<strong>β1</strong> : cœur (↑ fréquence, ↑ contractilité, ↑ conduction), rein (↑ rénine). <strong>β2</strong> : bronchodilatation, vasodilatation musculaire, relaxation utérine, glycogénolyse.', '<strong>Muscariniques M2</strong> : cœur (↓ fréquence). <strong>M3</strong> : bronchoconstriction, sécrétions, contraction vésicale, myosis.', 'Sympathique = « fight or flight » : tachycardie, hypertension, bronchodilatation, hyperglycémie, inhibition digestive. Parasympathique = « rest and digest ».']) + KEY('sky', 'Les bêtabloquants (β1) ralentissent le cœur ; les β2-mimétiques (salbutamol) dilatent les bronches ; l’atropine (antimuscarinique) accélère le cœur et dilate la pupille. Le baroréflexe module les deux systèmes en quelques secondes.') },
  { id: 'physiologie-cardio', subject: 'physiologie', title: 'Physiologie cardiaque et pression artérielle', summary: 'Automatisme, cycle cardiaque, débit, loi de Starling et régulation de la pression.',
    content: H3('Cœur et circulation') + H4('Automatisme et conduction') + UL(['<strong>Nœud sinusal</strong> (pacemaker, 60-100/min) → oreillettes → <strong>nœud auriculo-ventriculaire</strong> (ralentissement ≈ 0,1 s) → faisceau de His → branches → fibres de Purkinje.', 'Potentiel d’action des cellules nodales : dépolarisation lente diastolique (courant If, Ca2+), pas de plateau ; celui des cardiomyocytes a un <strong>plateau calcique</strong> (phase 2) responsable de la longue période réfractaire.', 'ECG : onde P (dépolarisation auriculaire), QRS (dépolarisation ventriculaire), T (repolarisation ventriculaire). PR ≈ 0,12-0,20 s, QRS &lt; 0,12 s.']) + H4('Cycle cardiaque') + UL(['<strong>Systole</strong> : contraction isovolumétrique (valves fermées) puis éjection (ouverture des sigmoïdes). <strong>Diastole</strong> : relaxation isovolumétrique puis remplissage (ouverture des valves auriculo-ventriculaires).', 'B1 = fermeture mitrale/tricuspide (début de systole), B2 = fermeture aortique/pulmonaire (début de diastole).', 'Volume télédiastolique ≈ 120 mL, télésystolique ≈ 50 mL, <strong>VES ≈ 70 mL</strong>, fraction d’éjection ≈ 60 %.', '<strong>Débit cardiaque</strong> Qc = FC × VES ≈ 5 L/min. <strong>Loi de Frank-Starling</strong> : plus le remplissage (précharge) est grand, plus la contraction est forte.', 'Déterminants du VES : précharge (retour veineux), contractilité (inotropisme, sympathique), postcharge (résistances artérielles).']) + H4('Pression artérielle') + UL(['<strong>PAM = Qc × RPT</strong> (résistances périphériques totales) ; PAM ≈ PAD + (PAS − PAD)/3 ≈ 93 mmHg pour 120/80.', 'Régulation rapide : <strong>baroréflexe</strong> (sinus carotidien, crosse aortique → nerfs IX et X → tronc cérébral) ; ↑ PA ⇒ ↑ parasympathique, ↓ sympathique.', 'Régulation lente : rein et <strong>système rénine-angiotensine-aldostérone</strong> (angiotensine II vasoconstrictrice, aldostérone retient Na+ et eau), ADH, peptides natriurétiques.']) + KEY('sky', 'Les résistances dépendent surtout des artérioles (loi de Poiseuille : R ∝ 1/r⁴ ; un rayon divisé par 2 multiplie la résistance par 16). C’est pourquoi le tonus artériolaire commande la pression et la répartition du débit.') },
  { id: 'physiologie-respi', subject: 'physiologie', title: 'Physiologie respiratoire', summary: 'Mécanique ventilatoire, volumes, échanges gazeux, transport de l’O2 et du CO2, contrôle.',
    content: H3('La respiration') + H4('Mécanique ventilatoire') + UL(['Inspiration <strong>active</strong> : diaphragme (nerf phrénique, C3-C5) et intercostaux externes ; la pression intrapleurale devient plus négative, l’air entre.', 'Expiration au repos <strong>passive</strong> (élasticité pulmonaire) ; forcée : abdominaux et intercostaux internes.', '<strong>Compliance</strong> = ΔV/ΔP ; le <strong>surfactant</strong> (pneumocytes II) abaisse la tension superficielle et évite le collapsus alvéolaire (loi de Laplace).', 'Volumes : courant VT ≈ 500 mL, réserve inspiratoire ≈ 3 L, réserve expiratoire ≈ 1,2 L, résiduel ≈ 1,2 L ; <strong>capacité vitale</strong> ≈ 4,7 L ; CPT ≈ 6 L. Le VR ne se mesure pas par spirométrie.', 'Espace mort anatomique ≈ 150 mL ; ventilation alvéolaire = (VT − VD) × FR ≈ 4,2 L/min.']) + H4('Échanges et transport') + UL(['Diffusion selon la <strong>loi de Fick</strong> : proportionnelle à la surface (≈ 70 m²) et au gradient, inversement à l’épaisseur (0,5 µm).', 'PAO2 ≈ 100 mmHg, PaCO2 = 40 mmHg. Rapport ventilation/perfusion V/Q ≈ 0,8 en moyenne, plus élevé aux sommets.', '<strong>O2</strong> : 98,5 % lié à l’hémoglobine (1,34 mL/g), 1,5 % dissous. Courbe de dissociation sigmoïde ; déplacée à droite (libération facilitée) par ↑ CO2, ↑ H+, ↑ température, ↑ 2,3-DPG (effet Bohr).', '<strong>CO2</strong> : 70 % sous forme de bicarbonates (anhydrase carbonique du globule rouge, effet Hamburger Cl-/HCO3-), 23 % carbaminé, 7 % dissous.']) + H4('Contrôle') + UL(['Centres bulbo-pontiques ; stimulus principal = <strong>PaCO2</strong> via les chémorécepteurs centraux (pH du LCR). Les chémorécepteurs périphériques (carotidiens, nerf IX) répondent à l’hypoxie (PaO2 &lt; 60 mmHg).']) + KEY('sky', 'Hypoventilation ⇒ ↑ PaCO2 ⇒ acidose respiratoire ; hyperventilation ⇒ ↓ PaCO2 ⇒ alcalose. Le CO2 est 20 fois plus diffusible que l’O2 : une atteinte de la membrane alvéolo-capillaire donne une hypoxémie avant l’hypercapnie.') },
  { id: 'physiologie-renal', subject: 'physiologie', title: 'Physiologie rénale', summary: 'Néphron, filtration glomérulaire, réabsorption tubulaire, concentration des urines et régulation hormonale.',
    content: H3('Le rein') + H4('Le néphron') + UL(['≈ 1 million de néphrons par rein : glomérule (filtration) + tubule (proximal, anse de Henle, distal, collecteur).', 'Débit sanguin rénal ≈ 20 % du débit cardiaque (1,2 L/min) pour 0,5 % du poids.', 'Barrière de filtration : endothélium fenêtré, membrane basale (charges négatives), podocytes à fentes de filtration ; retient protéines &gt; 70 kDa et cellules.']) + H4('Filtration glomérulaire') + UL(['<strong>DFG ≈ 125 mL/min = 180 L/jour</strong> ; l’urine finale ≈ 1,5 L : 99 % réabsorbés.', 'Pression nette de filtration = P hydrostatique capillaire (≈ 55) − P oncotique (≈ 30) − P hydrostatique capsulaire (≈ 15) ≈ +10 mmHg.', 'Autorégulation entre 80 et 180 mmHg (réflexe myogénique, rétrocontrôle tubulo-glomérulaire par la macula densa).', 'Mesure : <strong>clairance</strong> C = U × V / P. Créatinine (estimation), inuline (référence). Clairance du PAH ≈ débit plasmatique rénal.']) + H4('Réabsorption et sécrétion') + UL(['<strong>Tube proximal</strong> : 65-70 % du Na+ et de l’eau, 100 % du glucose (SGLT2, seuil ≈ 1,8 g/L) et des acides aminés, bicarbonates.', '<strong>Anse de Henle</strong> : branche descendante perméable à l’eau, ascendante imperméable et réabsorbant NaCl (cotransport Na-K-2Cl, cible des diurétiques de l’anse) : <strong>multiplication à contre-courant</strong>, gradient cortico-papillaire jusqu’à 1 200 mOsm/L.', '<strong>Tube distal et collecteur</strong> : réglage fin. <strong>Aldostérone</strong> : réabsorption de Na+, sécrétion de K+ et H+. <strong>ADH</strong> : insertion d’aquaporines 2, réabsorption d’eau, urine concentrée.', 'Le rein sécrète la <strong>rénine</strong> (appareil juxtaglomérulaire), l’<strong>érythropoïétine</strong>, active la vitamine D (1α-hydroxylase).']) + KEY('sky', 'Sans ADH : diabète insipide, urines abondantes et diluées. Excès d’aldostérone : hypertension, hypokaliémie, alcalose. Le glucose apparaît dans les urines quand la glycémie dépasse le seuil de réabsorption (≈ 1,8 g/L).') },
  { id: 'physiologie-digestif-endocrino', subject: 'physiologie', title: 'Physiologie digestive et endocrinienne', summary: 'Sécrétions digestives, absorption, axes hormonaux, régulation de la glycémie et de la calcémie.',
    content: H3('Digestion et hormones') + H4('Tube digestif') + UL(['<strong>Estomac</strong> : HCl (cellules pariétales, pompe H+/K+ ATPase stimulée par gastrine, histamine H2, acétylcholine), pepsinogène (cellules principales), facteur intrinsèque (absorption de la B12 dans l’iléon).', '<strong>Pancréas exocrine</strong> : bicarbonates (sécrétine) et enzymes (CCK) : amylase, lipase, trypsinogène activé par l’entérokinase.', '<strong>Bile</strong> : sels biliaires (émulsion des lipides, micelles), cycle entéro-hépatique ; la CCK contracte la vésicule.', '<strong>Absorption</strong> : glucose et galactose par SGLT1 (Na+-dépendant), fructose par GLUT5 ; acides aminés par cotransport Na+ ; lipides → chylomicrons dans la lymphe ; fer dans le duodénum, B12 dans l’iléon terminal, eau surtout dans le jéjunum et le côlon.', 'Motricité : péristaltisme coordonné par le plexus myentérique (Auerbach), parasympathique stimulant, sympathique inhibiteur.']) + H4('Axes endocriniens') + UL(['<strong>Hypothalamo-hypophysaire</strong> : GnRH → LH/FSH ; TRH → TSH → T3/T4 ; CRH → ACTH → cortisol ; GHRH → GH → IGF-1 ; rétrocontrôles négatifs.', 'Post-hypophyse : <strong>ADH</strong> (osmolarité, volémie) et <strong>ocytocine</strong>.', 'Hormones peptidiques : récepteur membranaire, action rapide. Stéroïdes et thyroïdiennes : récepteur intracellulaire, action génomique lente, transport par protéines plasmatiques.']) + H4('Glycémie et calcémie') + UL(['<strong>Insuline</strong> (cellules β, après un repas) : entrée du glucose (GLUT4 muscle et adipocyte), glycogénogenèse, lipogenèse, anabolisme. <strong>Glucagon</strong> (cellules α, à jeun) : glycogénolyse et néoglucogenèse hépatiques. Adrénaline, cortisol, GH sont hyperglycémiants.', '<strong>PTH</strong> : ↑ calcémie (résorption osseuse, réabsorption rénale, activation de la vitamine D). <strong>Calcitriol</strong> : ↑ absorption intestinale de Ca2+. <strong>Calcitonine</strong> : ↓ calcémie (rôle mineur).']) + KEY('sky', 'Le glucose entre dans les cellules β par GLUT2 (insulino-indépendant) : la sécrétion d’insuline suit la glycémie. Les inhibiteurs de la pompe à protons bloquent la H+/K+ ATPase gastrique. Une hypocalcémie donne des crampes et une tétanie (hyperexcitabilité neuromusculaire).') },

  // ===== MÉDICAMENT =====
  { id: 'medicament-definitions', subject: 'medicament', title: 'Définitions, formes galéniques et voies d’administration', summary: 'Principe actif, excipients, spécialité, générique et choix de la voie.',
    content: H3('Qu’est-ce qu’un médicament ?') + H4('Définitions') + UL(['Médicament (Code de la santé publique) : substance présentée comme possédant des propriétés <strong>curatives ou préventives</strong>, ou pouvant être utilisée pour restaurer, corriger ou modifier des fonctions physiologiques ou établir un diagnostic.', '<strong>Principe actif</strong> (PA) : molécule responsable de l’effet. <strong>Excipients</strong> : sans activité, assurent forme, stabilité, goût ; certains sont « à effet notoire » (lactose, gluten, alcool).', '<strong>Spécialité</strong> : médicament préparé industriellement, avec AMM, nom de marque. <strong>Générique</strong> : même PA, même dose, même forme, bioéquivalent (AUC et Cmax dans 80-125 %), moins cher. <strong>Biosimilaire</strong> : équivalent d’un biomédicament.', 'DCI (dénomination commune internationale) : nom scientifique du PA (paracétamol), à utiliser en prescription.']) + H4('Formes galéniques') + UL(['Orales : comprimé (nu, pelliculé, gastro-résistant, à libération prolongée), gélule, sirop, solution buvable.', 'Parentérales : injectable IV, IM, SC ; formes stériles et apyrogènes.', 'Locales : pommade, crème, gel, collyre, suppositoire, patch transdermique, aérosol.', 'La galénique conditionne la <strong>vitesse de libération</strong> du PA (libération immédiate vs prolongée) et l’observance.']) + H4('Voies d’administration') + UL(['<strong>Orale</strong> : la plus simple, mais effet de premier passage hépatique et variabilité (alimentation, pH).', '<strong>Intraveineuse</strong> : biodisponibilité 100 %, effet immédiat, irréversible, risque infectieux.', '<strong>Sublinguale, rectale, transdermique, inhalée</strong> : évitent en partie le premier passage hépatique.', 'IM et SC : absorption progressive ; intrathécale : passe la barrière hémato-encéphalique.']) + KEY('teal', 'Un comprimé à libération prolongée ne doit pas être écrasé (libération massive). Bioéquivalence ne veut pas dire identité : les excipients peuvent différer. La voie IV est la seule qui donne F = 100 % par définition.') },
  { id: 'medicament-absorption-distribution', subject: 'medicament', title: 'Pharmacocinétique 1 : absorption et distribution', summary: 'Passage des membranes, biodisponibilité, premier passage, fixation protéique et volume de distribution.',
    content: H3('ADME : absorption et distribution') + H4('Absorption') + UL(['Passage des membranes surtout par <strong>diffusion passive</strong> : molécules petites, lipophiles, <strong>non ionisées</strong>. Un acide faible est non ionisé en milieu acide (estomac), une base faible en milieu basique (équation d’Henderson-Hasselbalch).', 'Transporteurs : diffusion facilitée, transport actif (glycoprotéine P qui rejette les médicaments hors de la cellule, cible d’interactions).', '<strong>Biodisponibilité F</strong> : fraction de la dose qui atteint la circulation générale sous forme inchangée, et vitesse à laquelle elle l’atteint. F = AUC orale / AUC IV (à dose égale).', '<strong>Effet de premier passage hépatique</strong> : après absorption intestinale, le PA traverse le foie par la veine porte et peut y être métabolisé avant d’atteindre la circulation : F ↓.', 'Facteurs : forme galénique, pH, vidange gastrique, alimentation, interactions (pansements gastriques), flux sanguin.']) + H4('Distribution') + UL(['<strong>Fixation aux protéines plasmatiques</strong> (albumine pour les acides, α1-glycoprotéine acide pour les bases) : seule la <strong>fraction libre</strong> est active, diffuse et est éliminée.', '<strong>Volume de distribution</strong> Vd = dose / C0 (L ou L/kg) : volume fictif ; faible (≈ 3-5 L) si le PA reste dans le plasma, très grand (&gt; 100 L) s’il se fixe dans les tissus (lipophile).', 'Barrières : hémato-encéphalique (jonctions serrées, seuls passent les lipophiles et les substrats de transporteurs), placentaire, hémato-testiculaire.', 'Chez l’obèse, Vd des lipophiles ↑ ; chez le nouveau-né, eau totale ↑ ; l’hypoalbuminémie ↑ la fraction libre.']) + KEY('teal', 'Un médicament fortement lié aux protéines (&gt; 90 %) et à marge thérapeutique étroite (AVK) est sensible aux interactions par déplacement de la liaison : la fraction libre augmente brutalement. La dose de charge dépend du Vd ; la dose d’entretien de la clairance.') },
  { id: 'medicament-metabolisme-elimination', subject: 'medicament', title: 'Pharmacocinétique 2 : métabolisme et élimination', summary: 'Réactions de phase I et II, cytochromes, clairance, demi-vie et état d’équilibre.',
    content: H3('ADME : métabolisme et élimination') + H4('Métabolisme') + UL(['Surtout hépatique. But : rendre la molécule plus <strong>hydrosoluble</strong> pour l’éliminer.', '<strong>Phase I</strong> (fonctionnalisation) : oxydation, réduction, hydrolyse ; enzymes du <strong>cytochrome P450</strong> (CYP3A4 ≈ 50 % des médicaments, CYP2D6, 2C9, 2C19, 1A2).', '<strong>Phase II</strong> (conjugaison) : glucuronidation, sulfatation, acétylation ; métabolites inactifs et hydrosolubles.', '<strong>Induction enzymatique</strong> (rifampicine, carbamazépine, millepertuis, tabac pour le 1A2) : ↑ métabolisme, ↓ efficacité des médicaments associés, effet retardé (jours). <strong>Inhibition</strong> (kétoconazole, macrolides, jus de pamplemousse) : ↑ concentrations, toxicité, effet rapide.', '<strong>Prodrogue</strong> : inactive, activée par le métabolisme (clopidogrel, énalapril, codéine → morphine par le CYP2D6). Polymorphisme génétique : métaboliseurs lents ou ultrarapides.']) + H4('Élimination') + UL(['<strong>Rénale</strong> : filtration glomérulaire (fraction libre), sécrétion tubulaire active, réabsorption passive (dépend du pH urinaire : alcaliniser les urines accélère l’élimination des acides faibles).', '<strong>Biliaire</strong> puis fécale ; cycle entéro-hépatique qui prolonge l’effet.', '<strong>Clairance</strong> Cl = volume de plasma épuré par unité de temps ; Cl totale = Cl rénale + Cl hépatique.', '<strong>Demi-vie</strong> t½ = 0,693 × Vd / Cl. Après 5 t½ : 97 % éliminé, ou état d’équilibre atteint en administration répétée. Intervalle entre prises ≈ t½ pour limiter les fluctuations.', 'Cinétique d’<strong>ordre 1</strong> (proportionnelle à la concentration, la plus fréquente) vs <strong>ordre 0</strong> (saturation, quantité constante par unité de temps : alcool, phénytoïne à forte dose).']) + KEY('teal', 'En insuffisance rénale, adapter la dose des médicaments à élimination rénale (clairance de la créatinine). La demi-vie ne dépend pas de la dose en cinétique d’ordre 1. Deux médicaments substrats du même CYP peuvent se gêner : c’est la première cause d’interaction pharmacocinétique.') },
  { id: 'medicament-pharmacodynamie', subject: 'medicament', title: 'Pharmacodynamie : cibles, agonistes et antagonistes', summary: 'Récepteurs, affinité, efficacité, courbes dose-effet, index thérapeutique.',
    content: H3('Ce que le médicament fait à l’organisme') + H4('Cibles') + UL(['<strong>Récepteurs</strong> membranaires (canaux ioniques, couplés aux protéines G, à activité enzymatique) ou nucléaires (stéroïdes, thyroïdiennes).', '<strong>Enzymes</strong> (IEC, statines, AINS sur les cyclo-oxygénases), <strong>transporteurs</strong> (ISRS sur la recapture de la sérotonine), <strong>canaux</strong> (inhibiteurs calciques), <strong>ADN</strong> (anticancéreux), cibles microbiennes (antibiotiques).']) + H4('Agonistes et antagonistes') + UL(['<strong>Affinité</strong> : capacité à se lier (constante de dissociation Kd). <strong>Efficacité</strong> (activité intrinsèque) : capacité à activer une fois lié.', '<strong>Agoniste plein</strong> : effet maximal. <strong>Agoniste partiel</strong> : affinité mais efficacité partielle ; il peut antagoniser un agoniste plein. <strong>Agoniste inverse</strong> : effet opposé sur un récepteur constitutivement actif.', '<strong>Antagoniste compétitif</strong> : même site, réversible ; décale la courbe dose-effet de l’agoniste vers la droite sans changer l’Emax (surmontable). <strong>Non compétitif</strong> : autre site ou liaison irréversible ; abaisse l’Emax.', 'Courbe dose-effet sigmoïde (échelle log) : <strong>EC50</strong> = concentration donnant 50 % de l’effet maximal (puissance) ; Emax = efficacité.', '<strong>Désensibilisation / tolérance</strong> à l’exposition prolongée (internalisation des récepteurs), <strong>hypersensibilité de sevrage</strong> à l’arrêt brutal (bêtabloquants).']) + H4('Marge thérapeutique') + UL(['<strong>Index thérapeutique</strong> = DL50 / DE50 (ou DT50 / DE50) ; étroit pour digoxine, lithium, AVK, aminosides : surveillance des concentrations plasmatiques.', 'Relation dose-effet graduelle (individu) vs quantale (proportion de répondeurs dans une population).', 'Variabilité : âge, génétique (pharmacogénétique), pathologie, interactions, observance.']) + KEY('teal', 'La naloxone (antagoniste compétitif des récepteurs opioïdes) lève une overdose de morphine car son effet est surmontable dans les deux sens. Un agoniste partiel comme la buprénorphine plafonne l’effet : moins de dépression respiratoire.') },
  { id: 'medicament-developpement', subject: 'medicament', title: 'Cycle de vie du médicament et essais cliniques', summary: 'De la molécule à l’AMM : phases précliniques et cliniques, méthodologie des essais, agences.',
    content: H3('Du laboratoire au patient') + H4('Développement') + UL(['≈ 10-15 ans, 1 à 2 milliards d’euros, 1 molécule sur 10 000 aboutit. Protection par brevet 20 ans (dont ≈ 10 après commercialisation).', '<strong>Préclinique</strong> : criblage, pharmacologie in vitro et animale, toxicologie (dose unique, répétée, génotoxicité, cancérogenèse, reproduction), pharmacocinétique animale.', '<strong>Phase I</strong> : 20-100 <strong>volontaires sains</strong> (sauf cancérologie), tolérance, doses, pharmacocinétique humaine.', '<strong>Phase II</strong> : 100-300 patients, recherche de dose, première efficacité (preuve de concept).', '<strong>Phase III</strong> : 1 000-5 000 patients, efficacité contre placebo ou traitement de référence, essai <strong>randomisé en double aveugle</strong>, base de l’AMM.', '<strong>Phase IV</strong> : après commercialisation, pharmacovigilance, populations non étudiées, effets rares.']) + H4('Méthodologie') + UL(['<strong>Randomisation</strong> : évite les biais de sélection, rend les groupes comparables. <strong>Double aveugle</strong> : évite les biais d’évaluation. <strong>Placebo</strong> : contrôle l’effet placebo et l’évolution naturelle.', 'Critère de jugement principal défini a priori ; analyse en <strong>intention de traiter</strong> (tous les randomisés) préférée au per-protocole.', 'Essais de supériorité, de non-infériorité, d’équivalence ; puissance et nombre de sujets nécessaires calculés avant.', 'Éthique : loi Jardé, consentement éclairé, comité de protection des personnes (CPP), déclaration d’Helsinki.']) + H4('Agences et AMM') + UL(['<strong>ANSM</strong> (France) : AMM nationale, pharmacovigilance, sécurité. <strong>EMA</strong> : procédure centralisée européenne. FDA aux États-Unis.', '<strong>HAS</strong> : évalue le service médical rendu (SMR) et l’amélioration du SMR (ASMR) ; le CEPS fixe le prix ; remboursement selon le SMR.', 'Autorisation d’accès précoce et compassionnel pour les maladies graves sans alternative.']) + KEY('teal', 'La phase I se fait chez le volontaire sain, la phase III chez de nombreux malades contre un comparateur, la phase IV après l’AMM. L’AMM juge la qualité, la sécurité et l’efficacité ; la HAS juge l’intérêt pour le remboursement.') },
  { id: 'medicament-effets-indesirables', subject: 'medicament', title: 'Effets indésirables, interactions et pharmacovigilance', summary: 'Types d’effets indésirables, interactions PK et PD, déclaration et populations à risque.',
    content: H3('La sécurité du médicament') + H4('Effets indésirables') + UL(['<strong>Type A</strong> (augmented) : liés à la dose et au mécanisme, prévisibles, fréquents (hypoglycémie sous insuline, saignement sous AVK, bradycardie sous bêtabloquant).', '<strong>Type B</strong> (bizarre) : indépendants de la dose, imprévisibles, rares, souvent immuno-allergiques ou idiosyncrasiques (choc anaphylactique à la pénicilline, agranulocytose).', 'Type C (chronique, dépendance), D (différé : cancer, tératogénicité), E (fin de traitement : sevrage), F (échec).', '<strong>Iatrogénie</strong> : ≈ 10 % des hospitalisations chez le sujet âgé, souvent évitable.']) + H4('Interactions') + UL(['<strong>Pharmacocinétiques</strong> : absorption (chélation par les pansements gastriques, modification du pH), distribution (déplacement protéique), métabolisme (induction/inhibition des CYP), élimination (compétition tubulaire).', '<strong>Pharmacodynamiques</strong> : addition (deux sédatifs), potentialisation, antagonisme (AINS et antihypertenseurs), même cible ou cibles opposées.', 'Associations <strong>contre-indiquées</strong>, déconseillées, avec précaution d’emploi, à prendre en compte (thésaurus ANSM).', 'Interactions avec l’alimentation (pamplemousse et CYP3A4, vitamine K et AVK) et l’alcool.']) + H4('Pharmacovigilance et populations') + UL(['Déclaration <strong>obligatoire</strong> pour les professionnels de santé (et ouverte aux patients) de tout effet indésirable suspecté, aux centres régionaux de pharmacovigilance (CRPV), via le portail signalement-sante.gouv.fr.', '<strong>Imputabilité</strong> : chronologie, sémiologie, réintroduction, bibliographie.', 'Populations à risque : <strong>grossesse</strong> (tératogénicité au 1er trimestre : thalidomide, isotrétinoïne, valproate ; CRAT), allaitement, enfant (posologie au poids), sujet âgé (fonction rénale ↓, polymédication), insuffisants rénaux et hépatiques.', 'Plan de gestion des risques, retrait du marché si le rapport bénéfice/risque devient défavorable (Mediator).']) + KEY('teal', 'Effet A = dose-dépendant et prévisible, effet B = allergique et imprévisible. Devant un effet inattendu, chercher une interaction sur un cytochrome. Toute prescription chez une femme en âge de procréer se pense en termes de grossesse possible.') },
  { id: 'medicament-prescription', subject: 'medicament', title: 'Prescription, dispensation et réglementation', summary: 'Ordonnance, listes, stupéfiants, bon usage, observance et rôle du pharmacien.',
    content: H3('Du prescripteur au patient') + H4('L’ordonnance') + UL(['Mentions obligatoires : identification du prescripteur, du patient (nom, âge, poids chez l’enfant), date, DCI, dosage, forme, posologie, voie, durée, nombre de renouvellements, signature.', 'Prescripteurs : médecins, chirurgiens-dentistes, sages-femmes (liste limitée), certains infirmiers et pédicures pour des produits définis.', 'Ordonnance simple, bizone (ALD), sécurisée (stupéfiants), d’exception, de médicaments à prescription restreinte (hospitalière, initiale hospitalière, spécialistes, surveillance particulière).']) + H4('Statut des médicaments') + UL(['<strong>Liste I</strong> : cadre rouge, toxiques, non renouvelable sauf mention ; ordonnance valable 3 mois. <strong>Liste II</strong> : cadre vert, dangereux, renouvelable sauf mention contraire ; 12 mois de traitement maximum.', '<strong>Stupéfiants</strong> : ordonnance sécurisée, posologie en toutes lettres, durée maximale 28 jours (7 ou 14 pour certains), délai de présentation 3 jours, chevauchement interdit.', 'Médicaments <strong>non listés</strong> : vente libre, conseil pharmaceutique ; certains en accès direct devant le comptoir.', 'Contraceptifs, substituts nicotiniques : régimes particuliers.']) + H4('Bon usage et observance') + UL(['Le pharmacien <strong>analyse</strong> l’ordonnance (interactions, contre-indications, posologies), peut refuser de délivrer, substitue par un générique sauf mention « non substituable » justifiée.', 'Automédication : responsabilité du patient, conseils du pharmacien ; risques du paracétamol (hépatotoxicité au-delà de 4 g/j) et des AINS.', '<strong>Observance</strong> ≈ 50 % dans les maladies chroniques : simplifier le schéma, éduquer, piluliers, entretiens pharmaceutiques.', 'Antibiotiques : bon usage pour limiter les résistances (durées courtes, spectre étroit).']) + KEY('teal', 'Liste I = cadre rouge, non renouvelable par défaut ; liste II = cadre vert, renouvelable par défaut ; stupéfiants = ordonnance sécurisée et posologie en lettres. Le pharmacien engage sa responsabilité : il n’est pas un simple exécutant.') },
  { id: 'medicament-classes', subject: 'medicament', title: 'Grandes classes thérapeutiques à connaître', summary: 'Antalgiques, anti-inflammatoires, anticoagulants, cardiovasculaire, antibiotiques : mécanismes et points de vigilance.',
    content: H3('Classes à connaître en première année') + H4('Douleur et inflammation') + UL(['<strong>Paracétamol</strong> : antalgique-antipyrétique, pas anti-inflammatoire ; hépatotoxique en surdosage (N-acétylcystéine).', '<strong>AINS</strong> (ibuprofène, kétoprofène) : inhibition des cyclo-oxygénases ⇒ ↓ prostaglandines ; ulcère gastrique, insuffisance rénale, contre-indiqués à partir du 6e mois de grossesse. Aspirine à faible dose : antiagrégant irréversible.', '<strong>Opioïdes</strong> (morphine, codéine, tramadol) : agonistes des récepteurs µ ; constipation, dépression respiratoire, dépendance ; antidote naloxone. Paliers OMS 1, 2, 3.', '<strong>Corticoïdes</strong> : anti-inflammatoires et immunosuppresseurs ; hyperglycémie, ostéoporose, infections, ne pas arrêter brutalement.']) + H4('Cardiovasculaire et sang') + UL(['<strong>IEC / sartans</strong> : bloquent le système rénine-angiotensine ; toux (IEC), hyperkaliémie, contre-indiqués pendant la grossesse.', '<strong>Bêtabloquants</strong> : ↓ fréquence et contractilité ; bradycardie, bronchospasme (β2), masquent l’hypoglycémie.', '<strong>Statines</strong> : inhibition de l’HMG-CoA réductase ; myalgies, surveillance hépatique.', '<strong>Anticoagulants</strong> : héparines (antithrombine, surveillance plaquettaire), AVK (antagonistes de la vitamine K, INR, nombreuses interactions), anticoagulants oraux directs (anti-Xa, anti-IIa). Antiagrégants : aspirine, clopidogrel.']) + H4('Anti-infectieux') + UL(['<strong>Bêtalactamines</strong> (pénicillines, céphalosporines) : inhibent la synthèse du peptidoglycane, bactéricides, allergies.', '<strong>Macrolides</strong> : inhibent la synthèse protéique (50S), inhibiteurs enzymatiques. <strong>Aminosides</strong> : néphro- et ototoxiques. <strong>Fluoroquinolones</strong> : tendinopathies, photosensibilité.', 'Résistances : bêtalactamases, modification de cible, efflux ; antibiogramme et spectre.']) + KEY('teal', 'Associer AINS + IEC + diurétique chez un sujet âgé déshydraté = insuffisance rénale aiguë (« triple whammy »). Le paracétamol reste l’antalgique de première intention ; l’aspirine est contre-indiquée chez l’enfant fébrile (syndrome de Reye).') },

  // ===== HISTOLOGIE / EMBRYOLOGIE =====
  { id: 'histo-epitheliums', subject: 'histo', title: 'Les épithéliums', summary: 'Classification des épithéliums de revêtement, jonctions, lame basale et épithéliums glandulaires.',
    content: H3('Les épithéliums') + H4('Caractères généraux') + UL(['Cellules <strong>jointives</strong>, polarisées (pôle apical / basal), reposant sur une <strong>lame basale</strong> (collagène IV, laminine), <strong>non vascularisées</strong> (nutrition par diffusion depuis le conjonctif sous-jacent), à renouvellement rapide.', 'Jonctions : <strong>serrées</strong> (zonula occludens, étanchéité), <strong>adhérentes</strong> (cadhérines, actine), <strong>desmosomes</strong> (filaments intermédiaires de kératine), <strong>communicantes</strong> (gap, connexines), hémidesmosomes vers la lame basale.', 'Spécialisations apicales : microvillosités (bordure en brosse intestinale, absorption), cils (respiratoire, trompes), stéréocils (épididyme).']) + H4('Épithéliums de revêtement') + UL(['Selon le nombre de couches : <strong>simple</strong>, <strong>stratifié</strong>, <strong>pseudostratifié</strong> (toutes les cellules touchent la lame basale, noyaux à des hauteurs différentes).', 'Selon la forme des cellules superficielles : pavimenteux, cubique, prismatique (cylindrique).', 'Exemples : pavimenteux simple = <strong>endothélium</strong> et mésothélium ; cubique simple = tubes rénaux, thyroïde ; prismatique simple = estomac, intestin ; pseudostratifié cilié = trachée, bronches ; pavimenteux stratifié kératinisé = <strong>épiderme</strong>, non kératinisé = œsophage, vagin ; <strong>urothélium</strong> (polymorphe) = voies urinaires.']) + H4('Épithéliums glandulaires') + UL(['<strong>Exocrines</strong> : produit déversé par un canal (tubuleuses, acineuses, tubulo-acineuses ; séreuses, muqueuses, mixtes). Modes de sécrétion : mérocrine (exocytose, la plupart), apocrine (perte de cytoplasme apical : glande mammaire), holocrine (destruction de la cellule : sébacée).', '<strong>Endocrines</strong> : pas de canal, sécrétion dans le sang, organisation en cordons (surrénale, hypophyse) ou vésicules (thyroïde).', 'Glandes amphicrines : pancréas (acini exocrines et îlots endocrines).']) + KEY('fuchsia', 'Un épithélium ne contient jamais de vaisseau : les capillaires restent dans le conjonctif sous la lame basale. Une métaplasie (épithélium respiratoire devenant pavimenteux chez le fumeur) est une adaptation réversible ; une dysplasie est précancéreuse.') },
  { id: 'histo-conjonctif', subject: 'histo', title: 'Tissus conjonctifs, cartilage et os', summary: 'Cellules, fibres et substance fondamentale ; variétés de conjonctif ; cartilage hyalin, élastique, fibreux ; tissu osseux.',
    content: H3('Les tissus conjonctifs') + H4('Composition') + UL(['Cellules <strong>dispersées</strong> dans une <strong>matrice extracellulaire</strong> abondante, tissu <strong>vascularisé</strong> (sauf cartilage), d’origine mésenchymateuse.', 'Cellules fixes : <strong>fibroblastes</strong> (synthèse des fibres et de la substance fondamentale), adipocytes. Cellules mobiles : macrophages, mastocytes (histamine, héparine), plasmocytes, lymphocytes, polynucléaires.', '<strong>Fibres</strong> : collagène (type I : derme, tendon, os ; type II : cartilage ; type III : réticuline ; type IV : lame basale), élastiques (élastine, aorte, poumon).', '<strong>Substance fondamentale</strong> : glycosaminoglycanes (acide hyaluronique), protéoglycanes, glycoprotéines d’adhérence (fibronectine, laminine) ; retient l’eau.']) + H4('Variétés') + UL(['Lâche (soutien des épithéliums, chorion), dense régulier (tendon, ligament) ou irrégulier (derme), élastique, réticulé (organes lymphoïdes, moelle), adipeux blanc (réserve, un gros vacuole) et brun (thermogenèse, multivacuolaire, mitochondries).']) + H4('Cartilage') + UL(['Chondrocytes dans des chondroplastes, matrice riche en collagène II et aggrécane ; <strong>avasculaire</strong>, nourri par le périchondre, croissance interstitielle et appositionnelle, réparation médiocre.', '<strong>Hyalin</strong> (articulaire, trachée, cartilage de croissance), <strong>élastique</strong> (pavillon de l’oreille, épiglotte), <strong>fibreux</strong> (disques intervertébraux, ménisques, symphyse pubienne).']) + H4('Tissu osseux') + UL(['Matrice minéralisée (hydroxyapatite) sur collagène I. <strong>Ostéoblastes</strong> (formation), <strong>ostéocytes</strong> (dans les ostéoplastes, reliés par canalicules), <strong>ostéoclastes</strong> (résorption, multinucléés, origine monocytaire).', 'Os <strong>compact</strong> (ostéons de Havers autour d’un canal vasculaire, lamelles concentriques) et os <strong>spongieux</strong> (travées, moelle). Périoste et endoste.', 'Ossification <strong>endochondrale</strong> (os longs, à partir d’un modèle cartilagineux, cartilage de conjugaison) et <strong>membranaire</strong> (os plats du crâne). Remodelage permanent régulé par PTH, calcitriol, œstrogènes.']) + KEY('fuchsia', 'Cartilage = avasculaire, donc cicatrisation lente ; os = très vascularisé, cicatrise par cal. Ostéoclaste = résorption, ostéoblaste = formation ; les œstrogènes freinent les ostéoclastes, d’où l’ostéoporose après la ménopause.') },
  { id: 'histo-musculaire', subject: 'histo', title: 'Le tissu musculaire', summary: 'Muscle strié squelettique, cardiaque et lisse : structure, sarcomère, contraction.',
    content: H3('Les tissus musculaires') + H4('Muscle strié squelettique') + UL(['Fibres = cellules géantes <strong>multinucléées</strong> (noyaux périphériques) issues de la fusion de myoblastes ; enveloppes : endomysium, périmysium, épimysium.', '<strong>Sarcomère</strong> (entre deux stries Z) : filaments fins d’<strong>actine</strong> (avec tropomyosine et troponine) et épais de <strong>myosine</strong> ; bande A (myosine), bande I (actine seule), zone H, ligne M. À la contraction, I et H se raccourcissent, A reste constante.', 'Contraction : Ca2+ libéré par le réticulum sarcoplasmique (triade : tubule T + 2 citernes) se fixe sur la troponine C, dégage les sites de l’actine, cycle des ponts actine-myosine consommant l’ATP (théorie du glissement).', 'Fibres de type I (lentes, rouges, oxydatives, endurance) et II (rapides, glycolytiques). Cellules satellites : régénération limitée.']) + H4('Muscle cardiaque') + UL(['Cellules <strong>mononucléées</strong> (noyau central), striées, ramifiées, reliées par des <strong>disques intercalaires</strong> (desmosomes + jonctions gap ⇒ syncytium fonctionnel).', 'Contraction involontaire, automatisme (cellules nodales), dépendance au Ca2+ extracellulaire, pas de régénération (cicatrice fibreuse après infarctus).']) + H4('Muscle lisse') + UL(['Cellules fusiformes mononucléées, <strong>sans striation</strong> (pas de sarcomère organisé), actine et myosine ancrées sur des corps denses.', 'Contraction lente, prolongée, peu coûteuse, commandée par le SNA, les hormones, l’étirement ; régulation par la <strong>calmoduline</strong> et la kinase des chaînes légères de myosine (pas de troponine).', 'Paroi des viscères creux, vaisseaux, utérus ; capacité de régénération et d’hypertrophie.']) + KEY('fuchsia', 'Squelettique : multinucléé, périphérique, volontaire ; cardiaque : mononucléé, central, disques intercalaires ; lisse : fusiforme, sans striation. Seule la bande A garde sa longueur pendant la contraction.') },
  { id: 'histo-nerveux', subject: 'histo', title: 'Le tissu nerveux', summary: 'Neurones, cellules gliales, myéline, nerf périphérique et barrière hémato-encéphalique.',
    content: H3('Le tissu nerveux') + H4('Le neurone') + UL(['Corps cellulaire (péricaryon) avec noyau, <strong>corps de Nissl</strong> (réticulum granulaire), neurofilaments ; <strong>dendrites</strong> (réception) et un <strong>axone</strong> unique (émission) né du cône d’émergence.', 'Classification morphologique : multipolaires (motoneurones, la majorité), bipolaires (rétine, olfaction), pseudo-unipolaires (ganglions sensitifs rachidiens).', 'Transport axonal antérograde (kinésine) et rétrograde (dynéine) ; cellules post-mitotiques.']) + H4('Cellules gliales') + UL(['<strong>Astrocytes</strong> : soutien, barrière hémato-encéphalique (pieds astrocytaires), recapture du glutamate, cicatrice gliale.', '<strong>Oligodendrocytes</strong> : myéline du SNC (un oligodendrocyte myélinise plusieurs axones). <strong>Cellules de Schwann</strong> : myéline du SNP (une cellule par segment d’un seul axone), guident la régénération.', '<strong>Microglie</strong> : macrophages résidents (origine mésodermique). <strong>Épendymocytes</strong> : bordent les ventricules, plexus choroïdes et LCR.', 'Substance grise = corps cellulaires et synapses ; substance blanche = axones myélinisés.']) + H4('Nerf périphérique et méninges') + UL(['Fibres regroupées en fascicules : endonèvre, périnèvre (barrière), épinèvre. Ganglions rachidiens (sensitifs) et végétatifs.', 'Nœuds de Ranvier entre deux segments de myéline ; conduction saltatoire.', 'Méninges : dure-mère, arachnoïde, pie-mère ; LCR dans l’espace sous-arachnoïdien, produit par les plexus choroïdes.']) + KEY('fuchsia', 'Sclérose en plaques : démyélinisation du SNC (oligodendrocytes) ; Guillain-Barré : démyélinisation périphérique (Schwann). La régénération axonale n’est possible que dans le SNP, grâce aux cellules de Schwann.') },
  { id: 'histo-fecondation-s1', subject: 'histo', title: 'Gamétogenèse, fécondation et première semaine', summary: 'Spermatogenèse, ovogenèse, fécondation, segmentation et blastocyste.',
    content: H3('De la gamétogenèse au blastocyste') + H4('Gamétogenèse') + UL(['<strong>Spermatogenèse</strong> : dans les tubes séminifères à partir de la puberté, en continu, ≈ 74 jours ; spermatogonie → spermatocyte I (méiose I) → spermatocyte II → spermatide → spermatozoïde (spermiogenèse) ; cellules de Sertoli (soutien, barrière hémato-testiculaire), cellules de Leydig (testostérone).', '<strong>Ovogenèse</strong> : débute pendant la vie fœtale ; les ovocytes I restent <strong>bloqués en prophase I</strong> jusqu’à la puberté ; à chaque cycle, un ovocyte achève la méiose I (1er globule polaire) et se bloque en <strong>métaphase II</strong> ; la méiose II ne s’achève qu’à la fécondation. Réserve finie, ménopause.', 'Cycle ovarien : phase folliculaire (FSH, œstrogènes), <strong>ovulation</strong> au 14e jour (pic de LH), phase lutéale (corps jaune, progestérone).']) + H4('Fécondation') + UL(['Dans le tiers externe de la <strong>trompe</strong> (ampoule), dans les 24 h suivant l’ovulation ; spermatozoïdes fécondants ≈ 48-72 h après capacitation.', 'Étapes : traversée de la corona radiata, fixation à la <strong>zone pellucide</strong> (ZP3), <strong>réaction acrosomique</strong>, fusion des membranes, <strong>réaction corticale</strong> (bloque la polyspermie), achèvement de la méiose II (2e globule polaire), formation des pronuclei, amphimixie ⇒ <strong>zygote</strong> diploïde.', 'Sexe génétique déterminé par le spermatozoïde (X ou Y).']) + H4('Première semaine') + UL(['<strong>Segmentation</strong> : mitoses sans croissance, migration tubaire ; 2 cellules (J1), 4, 8 (compaction), <strong>morula</strong> (J3-4, 16 cellules), entrée dans l’utérus.', '<strong>Blastocyste</strong> (J5) : cavité (blastocèle), <strong>trophoblaste</strong> (futur placenta) et <strong>bouton embryonnaire</strong> (masse cellulaire interne, futur embryon) ; éclosion hors de la zone pellucide (J5-6).', '<strong>Nidation</strong> (implantation) débute vers <strong>J6-J7</strong> au pôle embryonnaire, dans l’endomètre en phase sécrétoire, le plus souvent sur la face postérieure du corps utérin.']) + KEY('fuchsia', 'Ovocyte bloqué en prophase I dès la vie fœtale, puis en métaphase II à l’ovulation : la méiose féminine ne s’achève qu’avec la fécondation. La réaction corticale empêche la polyspermie. Une nidation dans la trompe = grossesse extra-utérine.') },
  { id: 'histo-s2-s3', subject: 'histo', title: 'Deuxième et troisième semaines : disque didermique et gastrulation', summary: 'Nidation, disque à deux puis trois feuillets, ligne primitive, notochorde et devenir des feuillets.',
    content: H3('Semaines 2 et 3') + H4('Deuxième semaine : le disque didermique') + UL(['Nidation achevée vers J12. Le trophoblaste se différencie en <strong>cytotrophoblaste</strong> (interne, prolifère) et <strong>syncytiotrophoblaste</strong> (externe, invasif, sécrète l’<strong>hCG</strong> détectée par les tests de grossesse, érode les vaisseaux maternels : lacunes).', 'Le bouton embryonnaire se clive en <strong>épiblaste</strong> (dorsal, cavité amniotique) et <strong>hypoblaste</strong> (ventral, vésicule vitelline primitive) : <strong>disque didermique</strong>.', 'Mésoderme extra-embryonnaire, cœlome externe ; l’embryon est relié au trophoblaste par le pédicule embryonnaire (futur cordon).', 'La semaine des « 2 » : 2 feuillets, 2 cavités, 2 couches de trophoblaste.']) + H4('Troisième semaine : gastrulation') + UL(['Apparition de la <strong>ligne primitive</strong> sur l’épiblaste (pôle caudal), avec le nœud de Hensen : définit les axes.', 'Les cellules épiblastiques s’invaginent : les premières remplacent l’hypoblaste ⇒ <strong>endoderme</strong> ; les suivantes forment le <strong>mésoderme</strong> intra-embryonnaire ; l’épiblaste restant devient l’<strong>ectoderme</strong>. Disque <strong>tridermique</strong>.', 'La <strong>notochorde</strong> (axe, induit la neurulation, persiste dans le nucleus pulposus). Membranes pharyngienne et cloacale sans mésoderme.', 'Mésoderme para-axial (somites : sclérotome, myotome, dermatome), intermédiaire (reins, gonades), latéral (somatopleure et splanchnopleure, cœlome interne).', 'Début de l’angiogenèse (îlots de Wolff et Pander) et du tube cardiaque, qui bat vers J21-22.']) + H4('Devenir des feuillets') + UL(['<strong>Ectoderme</strong> : épiderme et phanères, système nerveux (neuroectoderme), crêtes neurales (ganglions, mélanocytes, médullosurrénale, os de la face).', '<strong>Mésoderme</strong> : squelette, muscles, derme, cœur et vaisseaux, sang, reins, gonades, séreuses.', '<strong>Endoderme</strong> : épithéliums du tube digestif et de l’arbre respiratoire, foie, pancréas, thyroïde, vessie.']) + KEY('fuchsia', 'Semaine 2 = disque didermique, semaine 3 = gastrulation et trois feuillets, semaine 4 = neurulation et délimitation. L’hCG est produite par le syncytiotrophoblaste dès la nidation : c’est ce que dose le test de grossesse.') },
  { id: 'histo-neurulation-annexes', subject: 'histo', title: 'Neurulation, délimitation et annexes embryonnaires', summary: 'Tube neural, crêtes neurales, plicature, amnios, vésicule vitelline, allantoïde, cordon et placenta.',
    content: H3('Quatrième semaine et annexes') + H4('Neurulation') + UL(['Sous l’induction de la notochorde, l’ectoderme dorsal s’épaissit en <strong>plaque neurale</strong> (J18), se creuse en gouttière puis se ferme en <strong>tube neural</strong> (J22-28) : fermeture du neuropore antérieur (J25) puis postérieur (J27-28).', 'Le tube neural donne le SNC : vésicules cérébrales (prosencéphale, mésencéphale, rhombencéphale) et moelle ; sa lumière devient ventricules et canal épendymaire.', 'Les <strong>crêtes neurales</strong> se détachent et migrent : ganglions sensitifs et végétatifs, cellules de Schwann, mélanocytes, médullosurrénale, cellules C thyroïdiennes, squelette de la face.', 'Anomalies de fermeture : <strong>spina bifida</strong> (neuropore postérieur), anencéphalie (antérieur) ; prévention par l’<strong>acide folique</strong> avant la conception.']) + H4('Délimitation') + UL(['Plicature longitudinale (céphalique et caudale) et transversale (latérale) : le disque plat devient un cylindre, l’endoderme s’enroule en <strong>intestin primitif</strong> (antérieur, moyen relié à la vésicule vitelline, postérieur), l’amnios entoure l’embryon.']) + H4('Annexes') + UL(['<strong>Amnios</strong> : cavité amniotique, liquide protecteur (≈ 1 L à terme), formé à partir de l’épiblaste.', '<strong>Vésicule vitelline</strong> : hématopoïèse primitive, cellules germinales primordiales, régresse.', '<strong>Allantoïde</strong> : diverticule caudal, vaisseaux ombilicaux, vestige = ouraque.', '<strong>Cordon ombilical</strong> : 2 artères et 1 veine, gelée de Wharton.', '<strong>Placenta</strong> : villosités choriales (trophoblaste + mésoderme + vaisseaux fœtaux) baignant dans les lacunes de sang maternel (type <strong>hémochorial</strong>) ; échanges sans mélange des sangs ; fonctions endocrines (hCG, hPL, progestérone et œstrogènes dès le 2e-3e mois relayant le corps jaune) ; barrière imparfaite (alcool, médicaments, virus).']) + KEY('fuchsia', 'Fermeture du tube neural entre J22 et J28, souvent avant que la grossesse ne soit connue : d’où la supplémentation en folates dès le projet de grossesse. Cordon = deux artères (sang pauvre en O2 vers le placenta) et une veine (sang riche vers le fœtus).') },
  { id: 'histo-periode-embryonnaire', subject: 'histo', title: 'Période embryonnaire, fœtale et tératogenèse', summary: 'Calendrier du développement, organogenèse, périodes de sensibilité et principaux tératogènes.',
    content: H3('Du disque à la naissance') + H4('Calendrier') + UL(['<strong>Période embryonnaire</strong> : semaines 1 à 8 (jusqu’à J56), <strong>organogenèse</strong> : mise en place de tous les organes ; embryon de ≈ 3 cm à la fin.', '<strong>Période fœtale</strong> : de la 9e semaine à la naissance ; croissance et maturation (poumons tardifs : surfactant à partir de la 24e-28e semaine).', 'Datation : semaines de développement (depuis la fécondation) vs <strong>semaines d’aménorrhée</strong> (SA, depuis les dernières règles) = développement + 2. Terme = 41 SA = 39 semaines de développement ≈ 280 jours d’aménorrhée.', 'Repères : cœur bat à J22, bourgeons des membres S4-5, face S5-8, différenciation gonadique à partir de S7 (gène SRY), mouvements perçus vers 18-20 SA.']) + H4('Tératogenèse') + UL(['<strong>Période de sensibilité maximale</strong> : semaines 3 à 8 (organogenèse) ⇒ malformations. Avant (S1-2) : loi du tout ou rien (mort ou développement normal). Après (période fœtale) : anomalies fonctionnelles, retard de croissance.', 'Agents : <strong>médicaments</strong> (thalidomide : phocomélie ; isotrétinoïne ; valproate : spina bifida ; AVK ; IEC), <strong>alcool</strong> (syndrome d’alcoolisation fœtale, première cause non génétique de déficience intellectuelle), tabac (retard de croissance), <strong>infections</strong> TORCH (toxoplasmose, rubéole, CMV, herpès, syphilis, Zika), radiations, diabète maternel mal équilibré, hyperthermie.', 'Anomalies chromosomiques : trisomie 21 (dépistage combiné du 1er trimestre : clarté nucale + marqueurs sériques, ADN fœtal circulant), diagnostic par caryotype (amniocentèse, biopsie de trophoblaste).', 'Malformation (défaut primaire de développement), déformation (contrainte mécanique), disruption (destruction secondaire d’une structure normale).']) + KEY('fuchsia', 'Semaines 3 à 8 = fenêtre des malformations : c’est le moment où la femme ignore souvent sa grossesse. Toute prescription chez une femme en âge de procréer se pense en conséquence ; le CRAT donne l’information de référence.') },
];
